import {validateFile} from './attachments.js';
import {createLifecycleUI} from './lifecycle-ui.js';
import {loadLocalAI,prepareLocalAI} from './local-ai.js';
import {createStaffUI} from './staff-ui.js';
import {isStaff,roleNames} from './staff.js';
import {initI18n,getLanguage,getLocale} from './i18n.js';
import {seed,view,mutate,statuses,money,total,budget,uid,ensurePlatform,executionStatuses} from './core.js';
import {createMarketplace} from './market-ui.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 6h7l2 2h9v12H3zM3 6V4h7l2 2',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wallet:'M3 5h17v15H3zM3 5V3h15M15 10h6v6h-6z',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',help:'M9 9a3 3 0 1 1 5 2.2c-1.5 1-2 1.3-2 3M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M9 4H3v16h6M10 12h11m-4-4 4 4-4 4',close:'m6 6 12 12M6 18 18 6',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',building:'M4 22V3h16v19M8 7h2M14 7h2M8 12h2M14 12h2M8 17h2M14 17h2',menu:'M3 6h18M3 12h18M3 18h18',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',trend:'m3 17 7-7 4 4 7-10M15 4h6v6'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const brand=()=>`<div class="brand"><span class="brand-mark">${icon('shield',23)}</span>RenoLock <em>AI</em></div>`;
const badge=s=>`<span class="badge ${s}">${statuses[s]||esc(s)}</span>`;
const date=s=>new Intl.DateTimeFormat(getLocale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(s));
let cloudMode=false,cloudIdentity=null,cloudUnavailable=false;
let serverMode=false,state=null,local=null,route={page:'overview'},filter='all',search='',editor=null,register=false,busy=false;
const toast=(message,error=false)=>{const el=document.querySelector('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5000);};
async function api(path,data){let res;try{res=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});}catch{throw Error('Нет связи с сервером. Проверьте подключение и повторите действие.');}let json;try{json=await res.json();}catch{throw Error('Сервер вернул некорректный ответ');}if(!res.ok)throw Error(json.error||'Ошибка запроса');return json;}
function loadLocal(){try{const stored=JSON.parse(localStorage.getItem('renolock-demo-v1'));if(stored?.users&&stored?.projects)return ensurePlatform(stored);}catch{}return ensurePlatform(seed());}
function storeLocal(){localStorage.setItem('renolock-demo-v1',JSON.stringify(local));}
async function refresh(){if(serverMode)state=await api('state');else if(state)state=view(local,local.users.find(u=>u.id===state.user.id));}
async function action(name,data){if(serverMode)return (await api('action',{action:name,data})).result;const copy=structuredClone(local);const result=mutate(copy,state.user,name,data);if(name!=='estimate.prepare'){local=copy;storeLocal();}return result;}
function go(page,extra={}){route={page,...extra};filter='all';search='';editor=null;render();window.scrollTo(0,0);}
function cloudAuth(){app.innerHTML=`<div class="auth-layout"><section class="auth-story">${brand()}<div><div class="eyebrow">RENOLOCK AI</div><h1>Ваш ремонт.<br>Общее пространство.</h1><p>Проекты, сметы и согласования сохраняются в облачной базе и доступны участникам с разных устройств.</p></div><footer>Цены из прайса · AI API не подключён</footer></section><section class="auth-form"><div class="auth-inner"><div class="eyebrow">Облачная платформа</div><h2>${cloudIdentity?'Завершите регистрацию':'Вход и регистрация'}</h2>${cloudIdentity?`<p>Аккаунт: ${esc(cloudIdentity.email)}</p><form id="auth-form"><label class="field">Ваше имя<input name="name" autocomplete="name" maxlength="100" required></label><label class="field">Ваша роль<select name="role"><option value="client">Client — заказчик</option><option value="contractor">Contractor — подрядчик</option></select></label><p class="muted">Выберите роль внимательно. Менеджеров назначает администратор.</p><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Создать аккаунт</button></form><a class="link-btn" href="/signout-with-chatgpt?return_to=%2F" target="_top">Выйти из аккаунта</a>`:'<p>Войдите через ChatGPT, затем выберите роль заказчика или подрядчика. Дополнительный пароль не нужен.</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Войти через ChatGPT</a>'}<div class="divider">Попробовать без регистрации</div><button class="btn" data-act="cloud-demo">Открыть деморежим</button><p class="auth-note">Деморежим хранится отдельно в браузере и не изменяет реальные данные.</p></div></section></div>`;}
function auth(){if(cloudMode)return cloudAuth();if(cloudUnavailable){app.innerHTML='<div class="auth-inner"><h2>Сервер временно недоступен</h2><p>Данные не изменены. Обновите страницу, чтобы повторить подключение.</p><button class="btn" onclick="location.reload()">Обновить страницу</button></div>';return;}app.innerHTML=`<div class="auth-layout"><section class="auth-story">${brand()}<div><div class="eyebrow" style="color:#97bda7">Порядок в каждом изменении</div><h1>Ремонт меняется.<br>Доверие остаётся.</h1><p>От первой сметы до последних деталей — согласовывайте работы и держите бюджет под контролем.</p><div class="auth-preview"><div class="eyebrow" style="color:#97bda7">ЖК Nova · квартира 42</div><div class="budget-row"><span>Базовая смета</span><strong>2 400 000 ₸</strong></div><div class="budget-row"><span>Согласованные изменения</span><strong>+21 000 ₸</strong></div><div class="budget-row total"><span>Утверждённый бюджет</span><strong>2 421 000 ₸</strong></div><div class="progress"><div style="width:92%;background:#a6c6a3"></div></div><small style="color:#9ab9a7">${icon('shield',12)} Только подтверждённые расходы</small></div></div><footer>Прозрачный бюджет. Спокойный ремонт.</footer></section><section class="auth-form"><div class="auth-inner"><div class="eyebrow">Ваше рабочее пространство</div><h2>${register?'Создать аккаунт':'С возвращением'}</h2><p>${register?'Начните с роли в вашем проекте.':'Войдите, чтобы продолжить работу над проектами.'}</p>${!serverMode?'<div class="notice demo">Онлайн-песочница: данные сохраняются в этом браузере. Для демонстрации выберите роль ниже. Регистрация и защищённые аккаунты доступны в локальной серверной версии.</div>':`<form id="auth-form">${register?'<label class="field">Ваше имя<input name="name" autocomplete="name" maxlength="100" required placeholder="Имя и фамилия"></label>':''}<label class="field">Email<input type="email" name="email" autocomplete="email" required placeholder="name@company.kz"></label><label class="field">Пароль<input type="password" name="password" minlength="10" maxlength="200" autocomplete="${register?'new-password':'current-password'}" required placeholder="Не менее 10 символов"></label>${register?'<label class="field">Ваша роль<select name="role"><option value="contractor">Contractor — подрядчик</option><option value="client">Client — заказчик</option></select></label>':''}<div class="form-error" id="auth-error" role="alert"></div><button class="btn primary" type="submit">${register?'Зарегистрироваться':'Войти в аккаунт'} ${icon('arrow',16)}</button></form><div class="auth-switch">${register?'Уже есть аккаунт?':'Первый раз в RenoLock?'} <button class="link-btn" data-act="auth-switch">${register?'Войти':'Зарегистрироваться'}</button></div>`}<div class="divider">Попробовать на тестовых данных</div>${location.protocol==='https:'?'<button class="link-btn" data-act="cloud-return">Вернуться к облачному входу</button>':''}<div class="demo-buttons"><button class="btn" data-act="demo" data-role="contractor">${icon('building',16)} Подрядчик</button><button class="btn" data-act="demo" data-role="client">${icon('check',16)} Заказчик</button></div><div class="demo-buttons staff-demo"><button class="btn" data-act="demo" data-role="manager">${icon('list',16)} Менеджер</button><button class="btn" data-act="demo" data-role="admin">${icon('shield',16)} Администратор</button></div><div class="auth-note">Бесплатно · Без ключа API · Валюта KZT<br>Сметы по прайсу · Бесплатный локальный AI доступен на совместимых устройствах.</div></div></section></div>`;}
const navNames={'project-chat':'Чат проекта',notifications:'Уведомления',overview:'Обзор',projects:'Мои проекты',estimates:'Сметы и согласования',prices:'Прайс-лист',history:'Журнал решений',help:'Как это работает',project:'Проект',estimate:'Смета',editor:'Новая смета',report:'Финансовый отчёт'};
function render(){if(!state){auth();return;}const pending=state.estimates.filter(e=>e.status==='pending').length;
 app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace"><span class="workspace-icon">${icon('building',17)}</span><div><strong>${isStaff(state.user)?'Команда RenoLock':state.user.role==='contractor'?'Reno Studio':'Личный кабинет'}</strong><small>${({contractor:'Панель подрядчика',client:'Панель заказчика',manager:'Кабинет менеджера',admin:'Кабинет администратора'})[state.user.role]}</small></div></div><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div>${(isStaff(state.user)?staffUI.nav(state.user):[['catalog','search'],['requests','file'],...(state.user.role==='contractor'?[['myprofile','building']]:[]),['overview','grid'],['projects','folder'],['estimates','file'],...(state.user.role==='contractor'?[['prices','list']]:[]),['history','clock']]).map(([page,ico])=>`<button class="nav ${route.page===page||(page==='projects'&&route.page==='project')||(page==='estimates'&&['estimate','editor'].includes(route.page))?'active':''}" data-go="${page}">${icon(ico,18)} ${navNames[page]||marketplace.names[page]||staffUI.names[page]}${page==='estimates'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="helper-card">${icon('shield',20)}<strong style="display:block;margin-top:8px">Бюджет под защитой</strong><p>Никаких неожиданных расходов. Каждое изменение — с вашим решением.</p><button class="link-btn" data-go="help">Как это работает ${icon('arrow',12)}</button></div><div class="account"><span class="avatar">${esc(state.user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${esc(state.user.name)}</strong><small>${roleNames[state.user.role]}</small></div><button data-act="logout" title="Выйти" aria-label="Выйти">${icon('logout',16)}</button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-act="menu" aria-label="Открыть меню">${icon('menu',21)}</button><div class="breadcrumb">Рабочее пространство <span>/</span> ${navNames[route.page]||marketplace.names[route.page]||staffUI.names[route.page]}</div><div class="topbar-right"><button class="btn small" data-go="notifications" aria-label="Уведомления">${icon('clock',16)} <span>Уведомления</span> <span id="notification-count" class="count">${(state.notifications||[]).filter(n=>!n.readAt).length}</span></button><span class="mode"><i class="mode-dot"></i>${cloudMode?'Облако · D1':serverMode?'Сервер · SQLite':'Демо · в этом браузере'}</span><button class="btn subtle small" data-act="refresh" title="Обновить данные" aria-label="Обновить данные">↻</button><span class="avatar">${esc(state.user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span></div></header><div class="content">${!serverMode?'<div class="notice demo no-print">Демонстрационная песочница · Данные только в этом браузере · Для реальных аккаунтов и совместной работы запустите серверную версию из исходников.</div>':''}${content()}<div class="footer-note"><span>RenoLock AI · Контроль бюджета ремонта</span><span>Цены из прайса · AI API не подключён</span></div></div></main></div>`;
 if(route.page==='editor')bindEditor();
}
const heading=(title,sub,buttons='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`;
const createButton=()=>state.user.role==='contractor'?`<button class="btn primary" data-act="project-new">${icon('plus',16)} Новый проект</button>`:'';
const newEstimateButton=p=>state.user.role==='contractor'?`<button class="btn primary" data-act="estimate-new" ${p?`data-project="${p}"`:''}>${icon('plus',16)} Новая смета</button>`:'';
function stats(projects=state.projects){const ids=new Set(projects.map(p=>p.id));const es=state.estimates.filter(e=>ids.has(e.projectId));const bs=projects.map(p=>budget(p,es));return `<div class="stats"><div class="stat"><div class="stat-top">Активные проекты <span class="stat-icon">${icon('folder',16)}</span></div><div class="stat-value">${projects.length.toString().padStart(2,'0')}</div><small>Все ваши ремонтные проекты</small></div><div class="stat highlight"><div class="stat-top">Утверждённый бюджет <span class="stat-icon">${icon('wallet',16)}</span></div><div class="stat-value">${money(bs.reduce((s,b)=>s+b.current,0))}</div><small>Базовая смета + согласованные работы</small></div><div class="stat"><div class="stat-top">На согласовании <span class="stat-icon">${icon('clock',16)}</span></div><div class="stat-value">${es.filter(e=>e.status==='pending').length.toString().padStart(2,'0')}</div><small>${money(bs.reduce((s,b)=>s+b.pending,0))} ожидает решения</small></div><div class="stat"><div class="stat-top">Согласовано дополнительно <span class="stat-icon">${icon('check',16)}</span></div><div class="stat-value">${money(bs.reduce((s,b)=>s+b.approved,0))}</div><small>${es.filter(e=>e.status==='approved').length} ${es.filter(e=>e.status==='approved').length===1?'смета утверждена':'смет согласовано'}</small></div></div>`;}
const floorplan=()=>`<svg viewBox="0 0 280 220" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M35 35h210v150H35zM35 100h75V35m0 65v85m0-65h135M180 35v85M180 60h65M35 155h75M150 120v65" stroke-width="5"/><path d="M48 48h48v39H48zM193 76h38v30h-38zM126 47h40v55h-40zM166 136h64v34h-64zM48 113h49v28H48zM48 164h48M67 164v12M132 134v36M225 136v34"/><path d="M20 24h240M20 195h240M20 24v171M260 24v171" stroke-dasharray="2 4" stroke-width="1"/></svg>`;
function projectCard(p){const b=budget(p,state.estimates),pending=state.estimates.filter(e=>e.projectId===p.id&&e.status==='pending').length;return `<article class="project-card"><div class="project-cover ${p.id==='terrace'?'terrace':''}">${floorplan()}<span class="badge ${pending?'pending':'approved'}">${pending?'Ожидает согласования':'В работе'}</span><span class="cover-caption">${esc(p.area)} м² · Residential</span></div><div class="project-info"><h3>${esc(p.name)}</h3><p>${icon('building',11)} ${esc(p.address)}</p><div class="project-numbers"><span class="muted">Текущий бюджет</span><strong>${money(b.current)}</strong></div><div class="progress"><div style="width:${Math.min(100,b.initial/b.current*100)}%"></div></div><div class="project-numbers" style="font-size:9px"><span class="muted">Базовая смета</span><span class="muted">${money(b.initial)}</span></div><div class="project-footer"><span>${pending?`${pending} смета на согласовании`:esc(p.clientEmail)}</span><button class="link-btn" data-go="project" data-id="${p.id}">Открыть ${icon('arrow',13)}</button></div></div></article>`;}
const empty=(msg)=>`<div class="empty">${icon('folder',28)}${msg}</div>`;

function executionBadge(e){if(e.status!=='approved')return '';const x=e.execution||{status:'not_started'};return `<span class="badge ${x.status==='delayed'?'rejected':x.status==='done'?'approved':'draft'}">${executionStatuses[x.status]}${x.status==='delayed'?' · '+x.delayDays+' дн.':''}</span>`;}
function executionPanel(e,readOnly=false){if(e.status!=='approved')return '';const x=e.execution;return `<section class="panel"><div class="panel-head"><h2>Выполнение согласованных работ</h2>${executionBadge(e)}</div><div class="panel-body"><p class="muted">Статус сообщает подрядчик. Это не подтверждение приёмки или оплаты. Изменение хода работ не меняет согласованную сумму.</p>${x?.reason?'<p>'+esc(x.reason)+'</p>':''}${x?'<small>'+esc(x.actor)+' · '+date(x.at)+'</small>':''}${!readOnly&&!['awaiting','accepted'].includes(e.acceptance?.status)&&state.user.role==='contractor'&&!state.projects.find(p=>p.id===e.projectId)?.completedAt?'<p><button class="btn" data-act="execution-edit" data-id="'+e.id+'">Обновить выполнение</button></p>':''}<details><summary>История выполнения</summary>${(e.executionHistory||[]).map(h=>'<p><strong>'+executionStatuses[h.status]+(h.status==='delayed'?' · '+h.delayDays+' дн.':'')+'</strong><br>'+esc(h.reason||'')+'<br><small>'+esc(h.actor)+' · '+date(h.at)+'</small></p>').join('')||'<p>Изменений пока нет.</p>'}</details></div></section>`;}
function executionModal(id){const e=state.estimates.find(e=>e.id===id),x=e.execution||{status:'not_started'};openModal('Обновить выполнение',`<form id="execution-form" data-id="${esc(id)}" data-version="${e.executionVersion||0}"><label class="field">Статус выполнения<select name="status">${Object.entries(executionStatuses).map(([key,label])=>'<option value="'+key+'" '+(key===x.status?'selected':'')+'>'+label+'</option>').join('')}</select></label><label class="field">Задержка, дней<input name="delayDays" type="number" min="1" max="3650" step="1" value="${x.delayDays||''}"><small>Обязательно только для статуса «Задержано». Это оценка подрядчика, не автоматический расчёт по календарю.</small></label><label class="field">Причина / комментарий<textarea name="reason" maxlength="1000">${esc(x.reason||'')}</textarea><small>Причина обязательна при задержке.</small></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Сохранить выполнение</button></form>`);}

function estimateTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Смета / проект</th><th>Статус</th><th class="right">Сумма</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${esc(state.projects.find(p=>p.id===e.projectId)?.name)}</small></td><td>${badge(e.status)} ${executionBadge(e)}</td><td class="right"><strong>${money(total(e.lines))}</strong></td><td class="right"><button class="link-btn" data-go="estimate" data-id="${e.id}" aria-label="Открыть смету ${esc(e.title)}">${icon('arrow',17)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Смет пока нет. Начните с нового проекта или создайте дополнительную смету.');}
const latestLogs=()=>[...state.logs].sort((a,b)=>b.at.localeCompare(a.at));
function activity(logs){return logs.length?logs.slice(0,4).map(l=>`<div class="activity"><span class="activity-dot">${icon(l.action==='approved'?'check':'clock',14)}</span><div><p><strong>${esc(statuses[l.action]||({saved:'Черновик обновлён',project:'Создан проект'}[l.action])||l.action)}</strong></p><small>${esc(state.projects.find(p=>p.id===l.projectId)?.name)} · ${date(l.at)}</small></div></div>`).join(''):empty('Здесь появится история ваших решений.');}
function content(){
 if(route.page==='notifications')return life.inbox();if(route.page==='project-chat')return life.chatPage(route.id);
 const staffContent=staffUI.content(route);if(staffContent!==null)return staffContent;
 const marketContent=marketplace.content(route);if(marketContent!==null)return marketContent;
 if(route.page==='overview')return `${heading('Всё под контролем','Проекты, сметы и решения — в одном рабочем пространстве.',createButton(),'Обзор проектов')}${stats()}<div class="cols"><section><div class="panel"><div class="panel-head"><h2>Ваши проекты <span class="muted">· ${state.projects.length}</span></h2><button class="link-btn" data-go="projects">Все проекты ${icon('arrow',13)}</button></div><div class="panel-body"><div class="project-grid">${state.projects.length?state.projects.slice(0,2).map(projectCard).join(''):empty('Создайте свой первый ремонтный проект.')}</div></div></div></section><aside><div class="ai-card"><span class="badge approved">${icon('spark',12)} Ассистент смет</span><h2>Опишите работу.<br>Получите черновик.</h2><p>Сопоставим работы с вашим прайсом. Вы проверите детали перед отправкой.</p>${state.user.role==='contractor'?`<button class="btn primary" data-act="estimate-new">${icon('spark',15)} Подготовить смету</button>`:`<button class="btn primary" data-go="estimates">Посмотреть сметы ${icon('arrow',14)}</button>`}<div class="mini-note">Режим правил · Без AI API и выдуманных цен</div></div></aside></div><div class="cols"><section class="panel"><div class="panel-head"><h2>Последние сметы</h2><button class="link-btn" data-go="estimates">Все сметы ${icon('arrow',13)}</button></div>${estimateTable([...state.estimates].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4))}</section><aside class="panel"><div class="panel-head"><h2>Последние события</h2>${icon('clock',16)}</div><div class="panel-body">${activity(latestLogs())}</div></aside></div>`;
 if(route.page==='projects')return `${heading('Мои проекты','От первоначальной сметы до согласованного бюджета.',createButton())}<div class="filter-bar"><input class="search" id="search" placeholder="Поиск по проектам…" aria-label="Поиск проектов" value="${esc(search)}"><span class="muted">${state.projects.length} проекта</span></div><div class="project-grid" id="project-results">${projectResults()}</div>`;
 if(route.page==='estimates')return `${heading('Сметы и согласования','Все дополнительные работы и статус каждого решения.',newEstimateButton())}<div class="tabs">${[['all','Все сметы'],...Object.entries(statuses)].map(([s,label])=>`<button class="tab ${filter===s?'active':''}" data-filter="${s}">${label} <small>${s==='all'?state.estimates.length:state.estimates.filter(e=>e.status===s).length}</small></button>`).join('')}</div><section class="panel">${estimateTable(state.estimates.filter(e=>filter==='all'||e.status===filter))}</section>`;
 if(route.page==='project'||route.page==='report')return projectPage();
 if(route.page==='estimate')return estimatePage();
 if(route.page==='editor')return editorPage();
 if(route.page==='prices')return pricesPage();
 if(route.page==='history')return `${heading('Журнал решений','Кто, когда и какую версию сметы согласовал.')}<div class="filter-bar"><select id="history-project" aria-label="Фильтр по проекту"><option value="all">Все проекты</option>${state.projects.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><section class="panel"><div class="panel-body">${logList(latestLogs().filter(l=>filter==='all'||l.projectId===filter))}</div></section>`;
 if(route.page==='help')return helpPage();
 return '';
}
function projectResults(){return state.projects.filter(p=>(p.name+' '+p.address).toLowerCase().includes(search.toLowerCase())).map(projectCard).join('')||empty('Проекты не найдены.');}
function budgetPanel(p){const b=budget(p,state.estimates);return `<section class="panel"><div class="panel-head"><h2>Бюджет проекта</h2>${icon('wallet',17)}</div><div class="panel-body"><div class="eyebrow">Утверждено к оплате</div><div class="stat-value" style="font-size:30px">${money(b.current)}</div><div class="budget-bar"><i style="width:${b.initial/b.current*100}%"></i><b style="width:${b.approved/b.current*100}%"></b></div><div class="legend"><span><i></i>Базовая смета</span><span><i class="light"></i>Дополнительные работы</span></div><div class="budget-row"><span class="muted">Первоначальная смета</span><strong>${money(b.initial)}</strong></div><div class="budget-row"><span class="muted">Согласовано дополнительно</span><strong style="color:var(--green)">+${money(b.approved)}</strong></div><div class="budget-row total"><span>Текущий бюджет</span><strong>${money(b.current)}</strong></div><div class="notice warning" style="margin:20px 0 0">На согласовании: <strong>${money(b.pending)}</strong><br>Эта сумма ещё не включена в бюджет. Это план согласованных расходов, не учёт фактических платежей.</div></div></section>`;}
function linesTable(lines){return `<div class="table-wrap"><table><thead><tr><th>Наименование</th><th>Объём</th><th class="right">Цена / ед.</th><th class="right">Сумма</th></tr></thead><tbody>${lines.map(l=>`<tr><td><strong>${esc(l.name)}</strong>${l.overrideReason?`<small>Изменение цены: ${esc(l.overrideReason)}</small>`:''}${l.catalogPrice?`<span class="cost-source">По прайсу: ${money(l.catalogPrice)} / ${esc(l.unit)}</span>`:''}</td><td>${esc(l.qty)} ${esc(l.unit)}</td><td class="right">${money(l.price)}</td><td class="right"><strong>${money(total([l]))}</strong></td></tr>`).join('')}<tr><td colspan="3"><strong>Итого</strong></td><td class="right"><strong>${money(total(lines))}</strong></td></tr></tbody></table></div>`;}

function financePanel(p){
 if(state.user.role!=='contractor'||p.contractorId!==state.user.id)return '';
 const f=state.contractorFinance?.find(f=>f.projectId===p.id),b=budget(p,state.estimates),planned=f?.plannedCost||0,spent=f?.actualCost||0,received=f?.received||0,profit=b.current-planned;
 const ratio=b.current>0?Math.min(100,received/b.current*100):0;
 return `<section class="panel contractor-finance"><div class="panel-head"><h2>Мои финансы проекта</h2><span class="badge draft">Только подрядчику</span></div><div class="panel-body"><div class="eyebrow">Стоимость согласованных работ</div><div class="stat-value">${money(b.current)}</div><p class="muted">Суммы на согласовании не включены.</p><div class="budget-row"><span>Получено от заказчика</span><strong>${money(received)}</strong></div><progress value="${ratio}" max="100" aria-label="Получено от стоимости договора" style="width:100%;accent-color:var(--green)"></progress><small>${Math.round(ratio)}% от стоимости договора</small>${received>b.current?'<p class="notice warning">Получено больше стоимости договора. Проверьте аванс и внесённые суммы.</p>':''}<div class="budget-row"><span>Осталось получить</span><strong>${money(Math.max(0,b.current-received))}</strong></div><div class="budget-row"><span>План расходов на весь проект</span><strong>${f?money(planned):'Не указан'}</strong></div><div class="budget-row total"><span>Плановая прибыль</span><strong>${f?money(profit):'Укажите план расходов'}</strong></div><p class="muted">${f?'Плановая маржа: '+(b.current?Math.round(profit/b.current*100):0)+'% · ':''}Стоимость работ минус план расходов. Не гарантированный заработок; учтите все расходы и налоги.</p><div class="budget-row"><span>Фактические расходы</span><strong>${money(spent)}</strong></div><div class="budget-row"><span>Остаток денежных средств</span><strong>${money(received-spent)}</strong></div><p class="muted">Получено минус фактические расходы. Итоги вводятся вручную, подключения к банку нет.</p>${f&&spent>planned?'<p class="notice warning">Фактические расходы превысили план. Обновите прогноз.</p>':''}<button class="btn" data-act="finance-edit" data-id="${p.id}">Обновить мои финансы</button>${f?'<p class="muted">Обновлено: '+date(f.updatedAt)+'</p>':''}</div></section>`;
}
function financeModal(id){const f=state.contractorFinance?.find(f=>f.projectId===id);openModal('Мои финансы проекта',`<form id="finance-form" data-id="${esc(id)}"><p class="notice">Введите накопленные итоги по проекту. Сохранение заменяет прежние суммы, а не добавляет платёж. Эти данные видны только вам и не меняют бюджет заказчика.</p>${[['plannedCost','План расходов на весь проект'],['actualCost','Фактические расходы'],['received','Получено от заказчика']].map(([key,label])=>'<label class="field">'+label+', ₸<input name="'+key+'" type="number" required min="0" max="1000000000" step="0.01" value="'+(f?.[key]??'')+'"></label>').join('')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Сохранить мои финансы</button></form>`);}
let localAIReady=false;
function localAIBox(){return `<section class="notice"><h3>Бесплатный локальный AI</h3><p>Qwen 0.5B работает на вашем устройстве через WebGPU. Первая загрузка — несколько сотен МБ; нужен совместимый Chrome/Edge и свободная память. Загрузка файлов идёт с CDN и Hugging Face. Текст сметы обрабатывается в браузере.</p><p>Модель может ошибаться. Цены берём только из прайса; результат — черновик для проверки.</p><button class="btn" data-act="ai-load">${localAIReady?'Модель загружена':'Загрузить бесплатную модель'}</button> <button class="btn primary" data-act="ai-prepare" ${localAIReady?'':'disabled'}>Подготовить с AI</button><p id="local-ai-status" role="status" aria-live="polite">${localAIReady?'AI готов. Проверьте результат перед сохранением.':'Модель ещё не загружена. Режим правил доступен без загрузки.'}</p></section>`;}

function projectPage(){const p=state.projects.find(p=>p.id===route.id);if(!p)return empty('Проект не найден.');const report=route.page==='report';return `${heading(esc(p.name),`${esc(p.address)} · ${esc(p.area)} м²`,report?`<button class="btn" data-go="project" data-id="${p.id}">Назад к проекту</button><button class="btn primary" data-act="print">${icon('down',15)} Печать / PDF</button>`:`<button class="btn" data-go="report" data-id="${p.id}">${icon('down',15)} Отчёт</button>${p.completedAt?'':newEstimateButton(p.id)}`,report?'Финансовый отчёт':'Ремонтный проект')}${report?'':marketplace.projectActions(p)}${!report&&['client','contractor'].includes(state.user.role)?'<div class="actions no-print" style="margin-bottom:18px"><button class="btn primary" data-act="life-chat" data-id="'+p.id+'">Чат проекта</button></div>':''}${life.panel('project',p,report)}<div class="notice ${report?'':'no-print'}">Заказчик: ${esc(p.clientEmail)} · Подрядчик: ${esc(state.people.find(u=>u.id===p.contractorId)?.name||state.user.name)}${report?`<br>Отчёт сформирован: ${date(new Date().toISOString())}. Валюта KZT. Статусы и суммы приведены на момент формирования.`:''}</div><div class="project-detail"><div><section class="panel"><div class="panel-head"><h2>Первоначальная смета</h2><span class="badge approved">Зафиксирована</span></div>${linesTable(p.baseline)}</section><section class="panel"><div class="panel-head"><h2>Дополнительные работы</h2><span class="muted">${state.estimates.filter(e=>e.projectId===p.id).length} смет</span></div>${estimateTable(state.estimates.filter(e=>e.projectId===p.id))}</section>${report?state.estimates.filter(e=>e.projectId===p.id).map(e=>`<section class="panel"><div class="panel-head"><h2>${esc(e.title)} · v${e.revision}</h2>${badge(e.status)}</div>${linesTable(e.lines)}</section>`).join(''):''}</div><aside>${!report?financePanel(p):''}${budgetPanel(p)}${!report?`<section class="panel"><div class="panel-head"><h2>События проекта</h2></div><div class="panel-body">${activity(latestLogs().filter(l=>l.projectId===p.id))}</div></section>`:''}</aside></div>${report?`<section class="panel"><div class="panel-head"><h2>История решений и версий</h2></div><div class="panel-body">${logList(latestLogs().filter(l=>l.projectId===p.id))}</div></section><div class="notice no-print">Для сохранения выберите «Печать / PDF», затем «Сохранить как PDF» в диалоге браузера. Отчёт включает базовую смету, все видимые дополнительные сметы и историю решений.</div>`:''}`;}
function logList(logs){return logs.length?logs.map(l=>`<article class="log-card"><div class="actions">${badge(l.action in statuses?l.action:l.action==='saved'?'draft':'approved')}<strong style="font-size:12px">${esc(l.actor)}</strong><span class="muted" style="margin-left:auto;font-size:10px">${date(l.at)}</span></div><p>${esc(state.estimates.find(e=>e.id===l.estimateId)?.title||state.projects.find(p=>p.id===l.projectId)?.name)} <span class="revision">· v${l.revision}</span></p>${l.comment?`<p class="muted">${esc(l.comment)}</p>`:''}<small>${money(l.amount)} · ${esc(state.projects.find(p=>p.id===l.projectId)?.name)}</small><details><summary>Состав сметы на момент события</summary>${linesTable(l.snapshot)}</details></article>`).join(''):empty('Решений пока нет.');}
function estimatePage(){const e=state.estimates.find(e=>e.id===route.id);if(!e)return empty('Смета недоступна.');const p=state.projects.find(p=>p.id===e.projectId);const edit=state.user.role==='contractor'&&['draft','changes'].includes(e.status);return `${heading(esc(e.title),`${esc(p.name)} · ${date(e.updatedAt)} · Версия ${e.revision}`,`<button class="btn" data-go="project" data-id="${p.id}">К проекту</button>${edit?`<button class="btn" data-act="estimate-edit" data-id="${e.id}">${icon('edit',15)} Редактировать</button>`:''}`,'Дополнительные работы')}<div class="step-strip"><span class="done">1. Подготовка</span><i class="line"></i><span class="${e.status!=='draft'?'done':''}">2. Согласование</span><i class="line"></i><span class="${e.status==='approved'?'done':''}">3. Обновление бюджета</span></div><div class="project-detail"><div><section class="panel"><div class="panel-head"><h2>Смета дополнительных работ</h2>${badge(e.status)}</div><div class="panel-body"><label class="field">Описание работ</label><div class="description">${esc(e.description)}</div></div>${linesTable(e.lines)}<div class="panel-body no-print">${edit?`<div class="notice">Перед отправкой проверьте объёмы, цены и состав работ. После отправки смета будет заблокирована для редактирования до решения клиента.</div><button class="btn primary" data-act="transition" data-status="pending" data-id="${e.id}">Отправить заказчику ${icon('arrow',15)}</button>`:e.status==='pending'&&state.user.role==='client'?`<label class="field">Комментарий к решению<textarea id="decision-comment" maxlength="1000" placeholder="Обязателен при отклонении или запросе изменений"></textarea></label><div class="actions"><button class="btn primary" data-act="transition" data-status="approved" data-id="${e.id}">${icon('check',15)} Утвердить смету</button><button class="btn" data-act="transition" data-status="changes" data-id="${e.id}">Запросить изменения</button><button class="btn danger" data-act="transition" data-status="rejected" data-id="${e.id}">Отклонить</button></div>`:`<div class="notice ${e.status==='pending'?'warning':''}">${e.status==='approved'?'Смета утверждена. Сумма включена в бюджет проекта.':e.status==='pending'?'Ожидаем решения заказчика. Сумма пока не включена в бюджет.':e.status==='rejected'?'Смета отклонена. Бюджет проекта не изменился.':'Заказчик запросил изменения. Подрядчик может отредактировать и отправить смету повторно.'}</div>`}</div></section>${executionPanel(e)}${life.panel('estimate',e)}<section class="panel"><div class="panel-head"><h2>История этой сметы</h2></div><div class="panel-body">${logList(latestLogs().filter(l=>l.estimateId===e.id))}</div></section></div><aside>${budgetPanel(p)}<div class="notice">${icon('shield',15)} Утверждённые и отклонённые сметы сохраняются без изменений. Прайс-лист не меняет ранее согласованные суммы.</div></aside></div>`;}
function pricesPage(){if(state.user.role!=='contractor')return empty('Прайс-лист доступен только подрядчику.');return `${heading('Прайс-лист','Ваши цены — единственный источник стоимости для новых смет.',`<button class="btn" data-act="price-import">${icon('down',15)} Импорт CSV</button><button class="btn primary" data-act="price-new">${icon('plus',15)} Добавить работу</button>`)}<div class="notice">Ассистент использует названия и ключевые слова из вашего прайса. Новая цена применяется при сохранении черновика. Отправленные и согласованные сметы хранят снимок цены.</div><section class="panel"><div class="panel-head"><h2>Работы и расценки</h2><span class="muted">${state.prices.filter(p=>p.active).length} активных позиций</span></div><div class="table-wrap"><table><thead><tr><th>Наименование работы</th><th>Единица</th><th class="right">Цена</th><th>Статус</th><th></th></tr></thead><tbody>${state.prices.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.aliases.join(', '))}</small></td><td>${esc(p.unit)}</td><td class="right">${money(p.price)}</td><td><span class="badge ${p.active?'approved':'draft'}">${p.active?'Активна':'В архиве'}</span></td><td><button class="link-btn" data-act="price-edit" data-id="${p.id}" aria-label="Редактировать ${esc(p.name)}">${icon('edit',15)}</button></td></tr>`).join('')||'<tr><td colspan="5">Добавьте первую работу или импортируйте прайс.</td></tr>'}</tbody></table></div></section>`;}
function helpPage(){return `${heading('От описания — к решению','Простой процесс, который сохраняет договорённости.')}<div class="help-grid">${[['01','Подрядчик готовит смету','Добавьте прайс, опишите работу с явным объёмом для каждой позиции. Например: «Выровнять 20 м2 стен; грунтовка 20 м2».'],['02','Заказчик принимает решение','Проверьте работы, объёмы и цены. Утвердите, отклоните или запросите изменения с комментарием.'],['03','Бюджет обновляется','Только утверждённая смета увеличивает бюджет. Снимки версий и комментарии остаются в журнале.']].map(([n,t,d])=>`<div class="panel"><div class="panel-body"><div class="big-num">${n}</div><h2>${t}</h2><p>${d}</p></div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Что означает AI в этой версии</h2>${icon('spark',18)}</div><div class="panel-body"><p>Платный AI API не подключён. Есть два режима: разбор по правилам без загрузки и необязательная генеративная модель Qwen 0.5B в браузере через WebLLM/WebGPU. Модель загружается отдельно с CDN, может ошибаться и требует проверки. Цены подставляются только из прайса. Режим правил использует названия и ключевые слова. Он ищет позицию в действующем прайсе, извлекает явный объём и рассчитывает стоимость обычным кодом. Неизвестные работы и неоднозначные описания требуют ручного уточнения. Алгоритм не понимает свободную речь как языковая модель.</p><p>Голосовой ввод — необязательная функция браузера. Он доступен при поддержке Web Speech API и разрешении на микрофон. Распознавание может обрабатываться сервисом браузера, зависеть от интернета и не гарантируется. Всегда можно ввести текст вручную.</p><p>${cloudMode?'Облачная версия использует вход через ChatGPT и базу D1. Участники видят общие проекты на разных устройствах. Демо хранится отдельно.':serverMode?'Серверная версия использует защищённую cookie-сессию и SQLite. Клиент видит только назначенные ему проекты. Для двух ролей войдите в разных браузерах или в приватном окне.':'Онлайн-демо использует localStorage и переключение тестовых ролей. Данные не синхронизируются между устройствами. Это песочница для показа интерфейса, а не защищённое многопользовательское хранилище.'}</p><p>Для демонстрации: откройте смету «Подготовка стен в гостиной» как заказчик, утвердите 58 000 ₸. Бюджет ЖК Nova изменится с 2 421 000 ₸ до 2 479 000 ₸.</p>${!serverMode?'<button class="btn danger" data-act="reset-demo">Сбросить тестовые данные</button>':''}</div></section>`;}
function startEditor(pId,e){if(state.user.role!=='contractor')return;const p=state.projects.find(p=>p.id===(pId||e?.projectId))||state.projects[0];if(!p){toast('Сначала создайте проект',true);return;}editor=e?structuredClone(e):{projectId:p.id,title:'',description:'',lines:[],revision:0};editor.unresolved=[];route={page:'editor'};render();window.scrollTo(0,0);}
function editorPage(){if(!editor)return empty('Откройте создание сметы из проекта.');return `${heading(editor.id?'Редактирование сметы':'Новая смета','Опишите работы, проверьте позиции и сохраните черновик.',`<button class="btn" data-go="project" data-id="${editor.projectId}">К проекту</button>`,'Ассистент смет')}<div class="project-detail"><section class="panel"><div class="panel-head"><h2>Описание дополнительных работ</h2><span class="badge draft">Черновик</span></div><div class="panel-body"><label class="field">Проект<select id="editor-project" ${editor.id?'disabled':''}>${state.projects.map(p=>`<option value="${p.id}" ${p.id===editor.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Название сметы<input id="editor-title" maxlength="200" value="${esc(editor.title)}" placeholder="Например, подготовка стен в гостиной"></label><label class="field">Что нужно сделать?<textarea id="editor-description" maxlength="5000" placeholder="Выровнять 20 м2 стен; грунтовка 20 м2">${esc(editor.description)}</textarea><small>Укажите объём каждой работы отдельно. Цена подставится из вашего прайса.</small></label><div class="actions"><button class="btn primary" data-act="prepare">${icon('spark',15)} Подготовить по прайсу</button><button class="btn" data-act="voice" id="voice-button">${icon('mic',15)} Голосовой ввод</button><button class="link-btn" data-act="example">Пример</button></div><div id="voice-status" class="muted" role="status" style="font-size:10px;margin-top:12px"></div><div class="notice" style="margin-top:16px">Режим правил · AI API не подключён. Ассистент не придумывает цены и не отправляет сметы без вашего участия.</div>${localAIBox()}<div id="unresolved"></div><h3 style="margin-top:24px">Состав сметы</h3><div class="editor-labels"><span>Работа из прайса</span><span>Объём</span><span>Цена / ед., ₸</span><span></span></div><div id="editor-lines"></div><button class="link-btn" data-act="line-add">${icon('plus',13)} Добавить позицию вручную</button><div class="estimate-total" id="editor-total"></div><div class="notice warning">Цена, отличающаяся от действующего прайса, требует пояснения. Проверьте все работы и объёмы перед сохранением.</div><div class="form-error" id="editor-error" role="alert"></div><button class="btn primary" data-act="estimate-save">Сохранить черновик ${icon('arrow',15)}</button></div></section><aside>${budgetPanel(state.projects.find(p=>p.id===editor.projectId))}<div class="panel"><div class="panel-body"><h3>${icon('shield',16)} Сначала проверка</h3><p class="muted" style="font-size:12px">Черновик виден только подрядчику. После сохранения его можно проверить ещё раз и отправить заказчику отдельным действием.</p></div></div></aside></div>`;}
function bindEditor(){renderLines();if(!(window.SpeechRecognition||window.webkitSpeechRecognition)){const btn=document.querySelector('#voice-button');btn.disabled=true;btn.title='Браузер не поддерживает голосовой ввод';document.querySelector('#voice-status').textContent='Голосовой ввод недоступен в этом браузере. Используйте текст.';}}
function syncEditor(){if(!editor)return;editor.title=document.querySelector('#editor-title')?.value||editor.title;editor.description=document.querySelector('#editor-description')?.value??editor.description;editor.projectId=document.querySelector('#editor-project')?.value||editor.projectId;}
function renderLines(){const box=document.querySelector('#editor-lines');if(!box)return;box.innerHTML=editor.lines.map((l,i)=>`<div class="line-editor" data-line="${i}"><select data-line-field="priceId" aria-label="Работа ${i+1}">${state.prices.filter(p=>p.active||p.id===l.priceId).map(p=>`<option value="${p.id}" ${p.id===l.priceId?'selected':''}>${esc(p.name)} · ${esc(p.unit)}${!p.active?' (архив)':''}</option>`).join('')}</select><input data-line-field="qty" type="number" min="0.01" max="1000000" step="0.01" value="${l.qty}" aria-label="Объём работы ${i+1}"><input data-line-field="price" type="number" min="0.01" step="0.01" value="${l.price}" aria-label="Цена работы ${i+1}"><button class="remove" data-act="line-remove" data-index="${i}" aria-label="Удалить позицию ${i+1}">${icon('close',15)}</button><label class="field reason">Пояснение изменения цены (если отличается от прайса)<input data-line-field="overrideReason" maxlength="500" value="${esc(l.overrideReason||'')}" placeholder="Например, сложная геометрия стены"></label></div>`).join('')||'<div class="empty" style="padding:20px">Позиции появятся после подготовки сметы.</div>';document.querySelector('#editor-total').innerHTML=`<small>Итого по черновику</small>${money(total(editor.lines))}`;document.querySelector('#unresolved').innerHTML=editor.unresolved?.length?`<div class="notice warning"><strong>Нужно уточнить — не включено в смету:</strong>${editor.unresolved.map(u=>`<p style="margin:7px 0">«${esc(u.text)}» — ${esc(u.reason)}</p>`).join('')}<p>Уточните описание и подготовьте заново либо добавьте нужную позицию вручную из прайса.</p><button class="btn small" data-act="resolve">Я проверил и обработал эти замечания</button></div>`:'';}
function openModal(title,body){modal.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button data-act="modal-close" aria-label="Закрыть">${icon('close',19)}</button></div>${body}`;modal.showModal();}
function projectModal(){openModal('Новый ремонтный проект',`<form id="project-form"><div class="form-grid"><label class="field">Название проекта<input name="name" required maxlength="200" placeholder="ЖК Nova · квартира 42"></label><label class="field">Площадь, м²<input name="area" type="number" min="1" max="100000" step="0.01" required placeholder="78"></label></div><label class="field">Адрес<input name="address" required maxlength="200" placeholder="Город, улица, дом"></label><label class="field">Email зарегистрированного заказчика<input name="clientEmail" required type="email" placeholder="client@renolock.demo"><small>Заказчик должен зарегистрироваться как Client. Демо: client@renolock.demo</small></label><h3>Первоначальная смета</h3><p class="muted" style="font-size:11px">После создания проекта базовая смета фиксируется. Изменения оформляются отдельными сметами.</p><div class="baseline-row muted" style="font-size:10px"><span>Работа</span><span>Ед.</span><span>Объём</span><span>Цена / ед., ₸</span><span></span></div><div id="baseline-lines"></div><button class="link-btn" type="button" data-act="baseline-add">+ Добавить работу</button><div class="estimate-total" id="baseline-total"></div><div class="form-error" id="modal-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-act="modal-close">Отмена</button><button class="btn primary" type="submit">Создать проект</button></div></form>`);addBaseline();}
function addBaseline(){const el=document.createElement('div');el.className='baseline-row';el.innerHTML='<input data-base="name" placeholder="Ремонт по договору" required maxlength="200" aria-label="Работа базовой сметы"><input data-base="unit" value="этап" required maxlength="20" aria-label="Единица"><input data-base="qty" type="number" min="0.01" step="0.01" value="1" required aria-label="Объём"><input data-base="price" type="number" min="0.01" step="0.01" placeholder="2400000" required aria-label="Цена"><button type="button" data-act="baseline-remove" aria-label="Удалить строку">×</button>';document.querySelector('#baseline-lines').append(el);updateBaseline();}
const readBaseline=()=>[...document.querySelectorAll('#baseline-lines .baseline-row')].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(input=>[input.dataset.base,['qty','price'].includes(input.dataset.base)?Number(input.value):input.value])));
function updateBaseline(){document.querySelector('#baseline-total').innerHTML=`<small>Начальный бюджет</small>${money(total(readBaseline()))}`;}
function priceModal(p){openModal(p?'Редактировать расценку':'Добавить работу',`<form id="price-form" data-id="${p?.id||''}"><label class="field">Название работы<input name="name" required maxlength="200" value="${esc(p?.name||'')}" placeholder="Выравнивание стен"></label><div class="form-grid"><label class="field">Единица<select name="unit">${['м²','м','шт'].map(u=>`<option ${p?.unit===u?'selected':''}>${u}</option>`).join('')}</select></label><label class="field">Цена за единицу, ₸<input name="price" type="number" min="0.01" max="1000000000" step="0.01" required value="${p?.price||''}"></label></div><label class="field">Ключевые слова через запятую<input name="aliases" value="${esc(p?.aliases.join(', ')||'')}" placeholder="выровнять, выравнивание"><small>Используются для поиска работы в тексте. Не добавляйте слишком общие слова.</small></label><label class="field">Статус<select name="active"><option value="true">Активна</option><option value="false" ${p?.active===false?'selected':''}>В архиве</option></select></label><div class="form-error" id="modal-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-act="modal-close">Отмена</button><button class="btn primary" type="submit">Сохранить</button></div></form>`);}
function importModal(){openModal('Импорт прайс-листа CSV',`<p class="muted" style="font-size:12px">UTF-8, разделитель «;». Первая строка: name;unit;price;aliases. Единицы: м², м, шт. Импорт добавляет новые позиции.</p><form id="import-form"><label class="field">CSV файл<input type="file" id="csv-file" accept=".csv,text/csv" required></label><div class="notice">Пример:<br>name;unit;price;aliases<br>Штукатурка стен;м²;2200;штукатурка,оштукатурить</div><div class="form-error" id="modal-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-act="modal-close">Отмена</button><button class="btn primary">Импортировать</button></div></form>`);}
async function loginDemo(role){if(serverMode){await api('auth',{email:role+'@renolock.demo',password:'RenoDemo2026!'});await refresh();}else{local=loadLocal();state=view(local,local.users.find(u=>u.role===role));sessionStorage.setItem('renolock-demo-user',state.user.id);}route={page:['manager','admin'].includes(role)?'staff-home':role==='client'?'catalog':'requests'};render();}
let recognition;
function voice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Голосовой ввод недоступен',true);if(recognition){recognition.stop();return;}const button=document.querySelector('#voice-button'),status=document.querySelector('#voice-status');const r=new SR();recognition=r;r.lang=({ru:'ru-RU',kk:'kk-KZ',en:'en-US'})[getLanguage()];r.interimResults=false;r.continuous=false;button.textContent='Остановить запись';status.textContent='Слушаем… Сервис браузера может обрабатывать аудио через интернет.';r.onresult=event=>{const input=document.querySelector('#editor-description');if(input){input.value+=(input.value?'\n':'')+event.results[0][0].transcript;syncEditor();}status.textContent='Текст добавлен. Проверьте распознавание перед расчётом.';};r.onerror=e=>status.textContent='Не удалось распознать речь ('+e.error+'). Используйте текстовый ввод.';r.onend=()=>{recognition=null;button.innerHTML=icon('mic',15)+' Голосовой ввод';};try{r.start();}catch{recognition=null;button.innerHTML=icon('mic',15)+' Голосовой ввод';status.textContent='Микрофон недоступен. Введите текст вручную.';}}
document.addEventListener('click',async event=>{
 const button=event.target.closest('button');if(!button)return;
 if(button.dataset.go){if(recognition)recognition.stop();go(button.dataset.go,{id:button.dataset.id});return;}
 if(button.dataset.filter){filter=button.dataset.filter;render();return;}
 const act=button.dataset.act;if(!act||busy)return;
 try{
 if(await life.click(act,button))return;
 if(await staffUI.click(act,button))return;
 if(await marketplace.click(act,button))return;
 switch(act){
 case 'cloud-demo':cloudMode=false;serverMode=false;local=loadLocal();auth();break;
 case 'cloud-return':sessionStorage.removeItem('renolock-demo-user');location.reload();break;
 case 'execution-edit':executionModal(button.dataset.id);break;
 case 'finance-edit':financeModal(button.dataset.id);break;
 case 'ai-load':openModal('Загрузка бесплатной AI-модели',`<p>Потребуется несколько сотен МБ трафика и память устройства. Модель загрузится с публичных CDN. Платного API нет.</p><div class="modal-actions"><button class="btn" data-act="modal-close">Отмена</button><button class="btn primary" data-act="ai-load-confirm">Начать загрузку</button></div>`);break;
 case 'ai-load-confirm':{modal.close();busy=true;const status=document.querySelector('#local-ai-status');try{status.textContent='Проверяем устройство и загружаем модель…';await loadLocalAI(text=>{if(status.isConnected)status.textContent=text;});localAIReady=true;status.textContent='AI готов. Проверьте результат перед сохранением.';document.querySelector('[data-act="ai-prepare"]').disabled=false;}catch(e){status.textContent='AI недоступен: '+e.message+' Режим правил остаётся доступен.';}break;}
 case 'ai-prepare':{syncEditor();if(editor.lines.length){openModal('Заменить позиции черновика?',`<p>AI заменит текущие позиции. Название и описание сохранятся.</p><button class="btn" data-act="modal-close">Отмена</button><button class="btn primary" data-act="ai-prepare-confirm">Заменить позиции</button>`);break;}await prepareAIEditor();break;}
 case 'ai-prepare-confirm':modal.close();await prepareAIEditor();break;
 case 'auth-switch':register=!register;auth();break;
 case 'demo':busy=true;button.disabled=true;await loginDemo(button.dataset.role);break;
 case 'logout':if(cloudMode){location.assign('/signout-with-chatgpt?return_to=%2F');break;}if(serverMode)await api('logout',{});sessionStorage.removeItem('renolock-demo-user');state=null;auth();break;
 case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;
 case 'refresh':await refresh();render();toast('Данные обновлены');break;
 case 'project-new':projectModal();break;
 case 'modal-close':modal.close();break;
 case 'baseline-add':addBaseline();break;
 case 'baseline-remove':button.closest('.baseline-row').remove();updateBaseline();break;
 case 'price-new':priceModal();break;
 case 'price-edit':priceModal(state.prices.find(p=>p.id===button.dataset.id));break;
 case 'price-import':importModal();break;
 case 'estimate-new':startEditor(button.dataset.project);break;
 case 'estimate-edit':startEditor(null,state.estimates.find(e=>e.id===button.dataset.id));break;
 case 'example':document.querySelector('#editor-description').value=({ru:'Выровнять 20 м2 стен; грунтовка 20 м2',kk:'Қабырғаны тегістеу 20 м2; қабырғаны астарлау 20 м2',en:'Wall leveling 20 m2; wall priming 20 m2'})[getLanguage()];document.querySelector('#editor-title').value||= ({ru:'Подготовка стен в гостиной',kk:'Қонақ бөлме қабырғаларын дайындау',en:'Living room wall preparation'})[getLanguage()];syncEditor();break;
 case 'voice':voice();break;
 case 'prepare':{syncEditor();if(editor.lines.length){openModal('Заменить позиции черновика?',`<p>Повторная подготовка заменит текущие позиции результатом разбора описания. Название и описание сохранятся.</p><div class="modal-actions"><button class="btn" data-act="modal-close">Отмена</button><button class="btn primary" data-act="prepare-confirm">Заменить позиции</button></div>`);break;}await prepareEditor();break;}
 case 'prepare-confirm':modal.close();await prepareEditor();break;
 case 'resolve':editor.unresolved=[];renderLines();toast('Замечания отмечены как обработанные');break;
 case 'line-add':{const p=state.prices.find(p=>p.active);if(!p){toast('Сначала добавьте активную позицию в прайс',true);break;}editor.lines.push({priceId:p.id,name:p.name,unit:p.unit,qty:1,price:p.price,catalogPrice:p.price,overrideReason:''});renderLines();break;}
 case 'line-remove':editor.lines.splice(Number(button.dataset.index),1);renderLines();break;
 case 'estimate-save':{syncEditor();if(editor.unresolved.length)throw Error('Обработайте замечания к описанию и подтвердите проверку.');busy=true;button.disabled=true;const e=await action('estimate.save',editor);await refresh();editor=null;go('estimate',{id:e.id});toast('Черновик сохранён. Проверьте и отправьте заказчику.');break;}
 case 'transition':{const e=state.estimates.find(e=>e.id===button.dataset.id);if(button.dataset.status==='approved'){const b=budget(state.projects.find(p=>p.id===e.projectId),state.estimates);openModal('Утвердить дополнительные работы?',`<p><strong>${esc(e.title)}</strong></p><div class="budget-row"><span>Дополнительная сумма</span><strong>${money(total(e.lines))}</strong></div><div class="budget-row total"><span>Новый бюджет проекта</span><strong>${money(b.current+total(e.lines))}</strong></div><p class="muted" style="font-size:12px;margin-top:16px">Решение сохранится в журнале. Утверждённую смету нельзя редактировать.</p><div class="modal-actions"><button class="btn" data-act="modal-close">Отмена</button><button class="btn primary" data-act="approve-confirm" data-id="${e.id}" data-revision="${e.revision}">Подтвердить ${money(total(e.lines))}</button></div>`);break;}await transition(e,button.dataset.status);break;}
 case 'approve-confirm':{const e=state.estimates.find(e=>e.id===button.dataset.id);await transition({...e,revision:Number(button.dataset.revision)},'approved');modal.close();break;}
 case 'print':window.print();break;
 case 'reset-demo':openModal('Сбросить песочницу?',`<p>Все изменения в онлайн-демо будут заменены исходными тестовыми данными.</p><div class="modal-actions"><button class="btn" data-act="modal-close">Отмена</button><button class="btn danger" data-act="reset-confirm">Сбросить</button></div>`);break;
 case 'reset-confirm':{const role=state.user.role;local=ensurePlatform(seed());storeLocal();state=view(local,local.users.find(u=>u.role===role));modal.close();go('overview');toast('Тестовые данные восстановлены');break;}
 }
 }catch(e){const err=document.querySelector('#editor-error');if(err&&act==='estimate-save')err.textContent=e.message;toast(e.message,true);}finally{busy=false;if(button.isConnected)button.disabled=false;}
});
async function prepareAIEditor(){busy=true;const status=document.querySelector('#local-ai-status');try{syncEditor();status.textContent='AI разбирает описание…';const result=await prepareLocalAI(editor.description,state.prices);editor.lines=result.lines;editor.unresolved=result.unresolved;renderLines();status.textContent='AI-черновик готов. Обязательно проверьте работы и объёмы.';}catch(e){status.textContent='AI недоступен: '+e.message+' Используйте режим правил.';}finally{busy=false;}}
async function prepareEditor(){busy=true;try{syncEditor();const result=await action('estimate.prepare',{projectId:editor.projectId,description:editor.description});editor.lines=result.lines;editor.unresolved=result.unresolved;renderLines();toast(result.unresolved.length?'Черновик подготовлен, нужны уточнения':'Позиции найдены в действующем прайсе');}finally{busy=false;}}
async function transition(e,status){busy=true;try{const comment=document.querySelector('#decision-comment')?.value||'';await action('estimate.transition',{id:e.id,revision:e.revision,status,comment});await refresh();render();toast(status==='approved'?'Смета утверждена. Бюджет обновлён.':status==='pending'?'Смета отправлена заказчику':status==='changes'?'Запрос на изменения сохранён':'Смета отклонена. Бюджет не изменился.');}finally{busy=false;}}
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.id==='search'){search=el.value;document.querySelector('#project-results').innerHTML=projectResults();}
 if(el.closest('#baseline-lines'))updateBaseline();
 if(el.id==='editor-title'||el.id==='editor-description')syncEditor();
 if(el.dataset.lineField){const row=el.closest('[data-line]'),line=editor.lines[Number(row.dataset.line)],field=el.dataset.lineField;line[field]=['qty','price'].includes(field)?Number(el.value):el.value;if(field==='priceId'){const p=state.prices.find(p=>p.id===el.value);Object.assign(line,{name:p.name,unit:p.unit,price:p.price,catalogPrice:p.price,overrideReason:''});renderLines();}else document.querySelector('#editor-total').innerHTML=`<small>Итого по черновику</small>${money(total(editor.lines))}`;}
});
document.addEventListener('change',event=>{if(event.target.id==='history-project'){filter=event.target.value;render();}if(event.target.id==='editor-project'){syncEditor();render();}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['auth-form','project-form','price-form','import-form','finance-form','execution-form'].includes(form.id))return;event.preventDefault();if(busy)return;busy=true;const btn=form.querySelector('button[type="submit"],button.primary');btn.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';
 try{
 const data=Object.fromEntries(new FormData(form));
 if(form.id==='execution-form'){await action('estimate.progress',{id:form.dataset.id,expectedVersion:Number(form.dataset.version),status:data.status,delayDays:Number(data.delayDays),reason:data.reason});await refresh();modal.close();render();toast('Статус выполнения сохранён');}
 if(form.id==='finance-form'){await action('finance.save',{projectId:form.dataset.id,plannedCost:Number(data.plannedCost),actualCost:Number(data.actualCost),received:Number(data.received)});await refresh();modal.close();render();toast('Мои финансы сохранены');}
 if(form.id==='auth-form'){await api('auth',{...data,register});await refresh();go(isStaff(state.user)?'staff-home':state.user.role==='client'?'catalog':'overview');}
 if(form.id==='project-form'){const p=await action('project.create',{...data,area:Number(data.area),baseline:readBaseline()});await refresh();modal.close();go('project',{id:p.id});toast('Проект создан. Базовая смета зафиксирована.');}
 if(form.id==='price-form'){await action('price.save',{...data,id:form.dataset.id||undefined,price:Number(data.price),active:data.active==='true'});await refresh();modal.close();render();toast('Прайс-лист сохранён');}
 if(form.id==='import-form'){
  const file=document.querySelector('#csv-file').files[0];if(!file||file.size>100000)throw Error('Выберите CSV до 100 КБ');const content=(await file.text()).replace(/^\uFEFF/,'');const rows=content.trim().split(/\r?\n/);if(rows.shift()!=='name;unit;price;aliases')throw Error('Неверный заголовок CSV');if(rows.length>100)throw Error('За один импорт можно добавить до 100 позиций');
  const parsed=rows.map((row,i)=>{const cols=row.split(';');if(cols.length!==4)throw Error(`Строка ${i+2}: ожидается 4 поля без кавычек и «;» внутри`);const [name,unit,raw,aliases]=cols.map(c=>c.trim());const price=Number(raw.replace(',','.'));if(!name||name.length>200||!['м²','м','шт'].includes(unit)||!(price>0&&price<=1e9))throw Error(`Проверьте строку ${i+2}`);return {name,unit,price,aliases};});
  let imported=0;try{for(const row of parsed){await action('price.save',row);imported++;}}catch(e){throw Error(`Импортировано ${imported} из ${parsed.length}. ${e.message}`);}finally{await refresh();}modal.close();render();toast(`Добавлено позиций: ${imported}`);
 }
 }catch(e){if(error)error.textContent=e.message;else toast(e.message,true);}finally{busy=false;if(btn.isConnected)btn.disabled=false;}
});

async function uploadChatFile(file,projectId){
 if(serverMode){const res=await fetch('/api/files?projectId='+encodeURIComponent(projectId)+'&name='+encodeURIComponent(file.name),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file});const json=await res.json();if(!res.ok)throw Error(json.error||'Не удалось загрузить файл');return json.file;}
 const bytes=new Uint8Array(await file.arrayBuffer()),info=validateFile(file.name,bytes);const demoData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать файл'));reader.readAsDataURL(file);});const copy=structuredClone(local);copy.files??=[];const item={id:crypto.randomUUID(),projectId,ownerId:state.user.id,...info,demoData};copy.files.push(item);try{localStorage.setItem('renolock-demo-v1',JSON.stringify(copy));}catch{throw Error('Недостаточно места в деморежиме. Попробуйте файл меньшего размера.');}local=copy;return item;
}

const life=createLifecycleUI({uploadFile:uploadChatFile,state:()=>state,esc,date,heading,empty,openModal,action,refresh,render,go,toast,closeModal:()=>modal.close()});
const staffUI=createStaffUI({lifecyclePanel:life.panel,executionPanel:(e,r)=>executionPanel(e,r)+life.panel('estimate',e,true),state:()=>state,esc,icon,money,total,budget,heading,empty,openModal,toast,action,refresh,render,go,date,badge,linesTable,logList,closeModal:()=>modal.close()});
const marketplace=createMarketplace({state:()=>state,serverMode:()=>serverMode,simulate:id=>{if(serverMode)throw Error("Недоступно на сервере");state=view(local,local.users.find(u=>u.id===id));sessionStorage.setItem("renolock-demo-user",id);go("requests");},esc,icon,money,total,heading,empty,openModal,toast,action,refresh,render,go,closeModal:()=>modal.close(),addBaseline,readBaseline,linesTable});
async function init(){if(location.protocol==='https:')cloudUnavailable=true;try{const res=await fetch('/api/health');const data=await res.json();serverMode=data.mode==='server';cloudMode=!!data.cloud;cloudUnavailable=false;if(cloudMode){try{cloudIdentity=await api('identity');}catch{}} }catch{serverMode=false;}
 if(cloudUnavailable){auth();return;}if(serverMode){try{await refresh();}catch{} if(isStaff(state?.user||{}))route={page:'staff-home'};render();}else{local=loadLocal();const id=sessionStorage.getItem('renolock-demo-user');if(id&&local.users.some(u=>u.id===id))state=view(local,local.users.find(u=>u.id===id));if(isStaff(state?.user||{}))route={page:'staff-home'};render();}}
function protectLifecycle(t,add){add(t.schedule?.pending,['reason','actor']);for(const h of t.schedule?.history||[])add(h,['reason','decisionReason','actor']);add(t.acceptance,['report','reason','actor']);for(const h of t.acceptanceHistory||[])add(h,['report','reason','actor']);}
initI18n({protectedTexts:()=>{
 const result=new Set();if(!state)return result;for(const f of state.files||[])result.add(f.name);for(const m of state.messages||[]){result.add(m.text);result.add(m.sender);}for(const n of state.notifications||[]){result.add(n.context);result.add(n.actor);}
 const add=(record,keys)=>{for(const key of keys)if(typeof record?.[key]==='string')result.add(record[key].trim());};
 add(state.user,['name','email']);
 for(const p of state.projects||[]){add(p,['name','address','clientEmail']);protectLifecycle(p,add);for(const l of p.baseline)add(l,['name']);}
 for(const e of state.estimates||[]){add(e,['title','description']);protectLifecycle(e,add);add(e.execution,['reason','actor']);for(const h of e.executionHistory||[])add(h,['reason','actor']);for(const l of e.lines)add(l,['name','overrideReason']);}
 for(const p of state.prices||[])add(p,['name']);
 for(const p of state.profiles||[]){add(p,['name','bio']);for(const w of p.portfolio)add(w,['title','description']);}
 for(const r of state.reviews||[])add(r,['text','author']);
 for(const r of state.requests||[]){add(r,['title','address','description','clientName','contractorName']);add(r.quote,['comment']);for(const event of r.events)add(event,['actor','comment']);}
 for(const l of state.logs||[])add(l,['actor','comment']);for(const n of state.projectNotes||[])add(n,['text','actor']);for(const t of state.tasks||[])add(t,['title']);for(const u of state.accounts||[])add(u,['name','email']);return result;
}});
document.addEventListener('renolock-language-change',()=>{if(recognition)recognition.stop();});
init();



let checkingNotifications=false;setInterval(async()=>{if(checkingNotifications||!state||!serverMode||document.hidden)return;checkingNotifications=true;try{const fresh=await api('state');if(state?.user.id===fresh.user.id){const messagesChanged=JSON.stringify(state.messages)!==JSON.stringify(fresh.messages||[]);const filesChanged=JSON.stringify(state.files)!==JSON.stringify(fresh.files||[]);state.files=fresh.files||[];state.messages=fresh.messages||[];if(messagesChanged||filesChanged)life.syncChat();const changed=JSON.stringify(state.notifications)!==JSON.stringify(fresh.notifications||[]);state.notifications=fresh.notifications||[];const badge=document.querySelector('#notification-count');if(badge)badge.textContent=state.notifications.filter(n=>!n.readAt).length;if(changed&&route.page==='notifications'&&!modal.open)render();}}catch{}finally{checkingNotifications=false;}},20000);



